export default function (pi) {
  pi.on("turn_end", (event) => {
    const content = event.message.content;
    const text = typeof content === "string" ? content : (content ?? []).map((p) => p.text ?? "").join("\n");
    if (!text.startsWith("LARGE_COMPLETED_RESPONSE")) return;
    return {
      entries: [
        ...event.entries,
        { type: "custom", customType: "other-extension-state", data: { preserved: true } },
        { type: "context_edit", targetId: "5eed0001", replacement: { content: "REPLACED_OWNER_INPUT" } },
        { type: "custom_message", customType: "continue-request", display: true, content: "Continue the inspection." },
      ],
      continue: true,
    };
  });
}
